    for r, row in enumerate(grid):
        c = row[0]
        if c not in (0, 9):
            seq[r % 6] = c

    known = [c for c in seq if c is not None]
    if not known:
        return [row[:] for row in grid]
    # Fill unobserved phases by continuing the observed bar sequence.
    for i in range(6):
        if seq[i] is None:
            seq[i] = known[i % len(known)]
    return [[seq[r % 6]] * w for r in range(h)]
