def transform(grid):
    h, w = len(grid), len(grid[0])
    # Treat contiguous full-width stripes as single objects. Their vertical
    # positions encode phases of the repeating row pattern.
    runs = []
    r = 0
    while r < h:
        c = grid[r][0]
        if c != 0:
            end = r
            while end + 1 < h and grid[end + 1][0] == c:
                end += 1
            runs.append((r, end, c))
            r = end + 1
        else:
            r += 1

    # Ignore the 9 divider stripes; the remaining stripes form the motif.
    bars = [(a, b, c) for a, b, c in runs if c != 9]
    period = len(bars)
    if not period:
        return [row[:] for row in grid]

    seq = [None] * period
    for a, b, c in bars:
        seq[a % period] = c

    # Fill phases not represented by a bar using the encountered color cycle.
    ordered = [c for _, _, c in bars]
    for i in range(period):
        if seq[i] is None:
            seq[i] = ordered[i % len(ordered)]
    return [[seq[r % period]] * w for r in range(h)]
