def transform(grid):
    h, w = len(grid), len(grid[0])
    bars = [(r, row[0]) for r, row in enumerate(grid)
            if row[0] != 0 and row[0] != 9]
    # The colored bars specify the color for their row phase in the repeating
    # vertical pattern. The phase period is the number of non-divider bars.
    period = len(bars)
    phase_colors = {}
    for r, color in bars:
        phase_colors[r % period] = color

    # Extend the phase pattern into phases without an explicit bar.
    known = sorted(phase_colors)
    for p in range(period):
        if p not in phase_colors:
            nearest = min(known, key=lambda q: min((p-q) % period, (q-p) % period))
            phase_colors[p] = phase_colors[nearest]

    return [[phase_colors[r % period]] * w for r in range(h)]
